export const getListPresentationCommentsUrl = (id: string,
    params?: ListPresentationCommentsParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : String(value))
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/api/presentations/${id}/comments?${stringifiedParams}` : `/api/presentations/${id}/comments`
}

